const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(weekStart.getDate() - 7);

const repoFull = ($env.GITHUB_REPO || '').trim();
if (!repoFull.includes('/')) {
  throw new Error('Set GITHUB_REPO to owner/repo (e.g. claude-builders-bounty/claude-builders-bounty).');
}
const [owner, repo] = repoFull.split('/');

const githubToken = ($env.GITHUB_TOKEN || '').trim();
const anthropicKey = ($env.ANTHROPIC_API_KEY || '').trim();
if (!githubToken) throw new Error('Set GITHUB_TOKEN with repo read access.');
if (!anthropicKey) throw new Error('Set ANTHROPIC_API_KEY.');

const language = (($env.SUMMARY_LANGUAGE || 'EN').trim().toUpperCase() === 'FR') ? 'FR' : 'EN';
const deliveryChannel = (($env.DELIVERY_CHANNEL || '').trim().toLowerCase());
const discordUrl = ($env.DISCORD_WEBHOOK_URL || '').trim();
const slackUrl = ($env.SLACK_WEBHOOK_URL || '').trim();
const emailTo = ($env.SUMMARY_EMAIL_TO || '').trim();

let channel = deliveryChannel;
if (!channel) {
  if (discordUrl) channel = 'discord';
  else if (slackUrl) channel = 'slack';
  else if (emailTo) channel = 'email';
}

if (!['discord', 'slack', 'email'].includes(channel)) {
  throw new Error('Set DELIVERY_CHANNEL to discord, slack, or email (and the matching destination variable).');
}
if (channel === 'discord' && !discordUrl) throw new Error('DELIVERY_CHANNEL=discord requires DISCORD_WEBHOOK_URL.');
if (channel === 'slack' && !slackUrl) throw new Error('DELIVERY_CHANNEL=slack requires SLACK_WEBHOOK_URL.');
if (channel === 'email' && !emailTo) throw new Error('DELIVERY_CHANNEL=email requires SUMMARY_EMAIL_TO.');

return [{
  json: {
    owner,
    repo,
    repoFullName: `${owner}/${repo}`,
    language,
    weekStart: weekStart.toISOString(),
    weekEnd: now.toISOString(),
    githubToken,
    anthropicApiKey: anthropicKey,
    deliveryChannel: channel,
    discordWebhookUrl: discordUrl,
    slackWebhookUrl: slackUrl,
    emailTo,
    emailFrom: ($env.SUMMARY_EMAIL_FROM || 'n8n@localhost').trim()
  }
}];

const config = $('Load Config').first().json;
const weekStart = new Date(config.weekStart);
const weekEnd = new Date(config.weekEnd);

const inWeek = (iso) => {
  if (!iso) return false;
  const d = new Date(iso);
  return d >= weekStart && d <= weekEnd;
};

let commits = [];
let issues = [];
let prs = [];

try {
  const raw = $('Fetch Commits').first().json;
  commits = Array.isArray(raw) ? raw.filter(c => inWeek(c.commit?.author?.date || c.commit?.committer?.date)) : [];
} catch (_) {}

try {
  const raw = $('Fetch Closed Issues').first().json;
  issues = Array.isArray(raw)
    ? raw.filter(i => !i.pull_request && inWeek(i.closed_at))
    : [];
} catch (_) {}

try {
  const raw = $('Fetch Merged PRs').first().json;
  prs = Array.isArray(raw)
    ? raw.filter(p => p.merged_at && inWeek(p.merged_at))
    : [];
} catch (_) {}

const contributors = {};
for (const c of commits) {
  const author = c.author?.login || c.commit?.author?.name || 'unknown';
  contributors[author] = (contributors[author] || 0) + 1;
}

const langLine = config.language === 'FR'
  ? 'Rédigez le résumé en français.'
  : 'Write the summary in English.';

const prompt = [
  `Repository: ${config.repoFullName}`,
  `Reporting window: ${config.weekStart.slice(0, 10)} to ${config.weekEnd.slice(0, 10)}`,
  '',
  `Commits (${commits.length}):`,
  ...commits.slice(0, 25).map(c => `- ${c.sha.slice(0, 7)} ${c.commit.message.split('\n')[0]} (${c.author?.login || c.commit.author?.name || 'unknown'})`),
  commits.length === 0 ? '- none' : '',
  '',
  `Closed issues (${issues.length}):`,
  ...issues.slice(0, 25).map(i => `- #${i.number} ${i.title}`),
  issues.length === 0 ? '- none' : '',
  '',
  `Merged pull requests (${prs.length}):`,
  ...prs.slice(0, 25).map(p => `- #${p.number} ${p.title} (by ${p.user?.login || 'unknown'})`),
  prs.length === 0 ? '- none' : '',
  '',
  'Produce a concise weekly narrative dev summary with sections: Highlights, Commits, Issues Resolved, Pull Requests Merged, and TL;DR.',
  'Use only facts from the data above. Do not invent work.',
  langLine
].filter(Boolean).join('\n');

return [{
  json: {
    config,
    stats: {
      commits: commits.length,
      issues: issues.length,
      prs: prs.length,
      contributors: Object.keys(contributors).length
    },
    claudeRequest: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 2048,
      messages: [{ role: 'user', content: prompt }]
    }
  }
}];

